/// Per-parameter standard deviations (sqrt of the marginal diagonal)
/// of one `Camera`; returns the count, or -1 (error) / -2 (panic) / -3
/// (no assembly or buffer too small), text via scene_cov_error.
/// Works on every CovMode, including TriDiagonal.
#[no_mangle]
pub unsafe extern "C" fn scene_camera_std_dev(
    c: *mut SceneCov,
    p: *const Camera,
    out: *mut f64,
    cap: u32,
) -> i32 {
    let cc = &mut *c;
    match catch_unwind(AssertUnwindSafe(|| cc.cov.std_dev(&*p))) {
        Ok(Ok(sd)) => {
            if sd.len() as u32 > cap {
                cov_text(cc, "std_dev: buffer too small");
                return -3;
            }
            for (i, v) in sd.iter().enumerate() {
                *out.add(i) = *v;
            }
            sd.len() as i32
        }
        Ok(Err(e)) => {
            cov_text(cc, &format!("{}", e));
            -1
        }
        Err(p2) => {
            let msg = panic_text(p2);
            cov_text(cc, &msg);
            -2
        }
    }
}

