/// Row-major pa x pb cross-covariance (f64) between a `Camera` and a
/// `Camera`; returns the row count, or -1 (error) / -2 (panic) / -3 (buffer too small), text via scene_cov_error.
#[no_mangle]
pub unsafe extern "C" fn scene_camera_camera_cross_cov(
    c: *mut SceneCov,
    a: *const Camera,
    b: *const Camera,
    out: *mut f64,
    cap: u32,
) -> i32 {
    let cc = &mut *c;
    match catch_unwind(AssertUnwindSafe(|| cc.cov.cross_cov(&*a, &*b))) {
        Ok(Ok(m)) => {
            let (rows, cols) = (m.nrows(), m.ncols());
            if (rows * cols) as u32 > cap {
                cov_text(cc, "cross_cov: buffer too small");
                return -3;
            }
            for r in 0..rows {
                for c in 0..cols {
                    *out.add(r * cols + c) = m[(r, c)];
                }
            }
            rows as i32
        }
        Ok(Err(e)) => {
            cov_text(cc, &format!("{}", e));
            -1
        }
        Err(p2) => {
            let msg = panic_text(p2);
            cov_text(cc, &msg);
            -2
        }
    }
}

