/// Appends `n` elements built from `n` slot records of 13 u64 each (mask
/// word(s), then one slot per leaf), or `n` defaults when `slots` is null.
/// Returns the first new element's key: its packed ref on a refs::Vec,
/// its index on a std::vec::Vec.
#[no_mangle]
pub unsafe extern "C" fn scene_cameras_push_n(p: *mut SceneHandle, slots: *const u64, n: u32) -> u32 {
    let m = &mut (*p).model.cameras;
    let first = m.len();
    m.reserve(n as usize);
    for i in 0..n as usize {
        let mut e: Camera = Default::default();
        if !slots.is_null() {
            assign_slots_camera(&mut e, slots.add(i * 13));
        }
        m.push(e);
    }
    if n == 0 { u32::MAX } else { m.ref_at(first).to_raw() }
}
/// Sets `t` on elements `start..start + n` from values `stride` bytes
/// apart (0 broadcasts one value); false when the range exceeds the collection.
#[no_mangle]
pub unsafe extern "C" fn scene_cameras_set_t_n(
    p: *mut SceneHandle, start: u32, v: *const f64, n: u32, stride: i64) -> bool {
    let m = &mut (*p).model.cameras;
    let (start, n) = (start as usize, n as usize);
    if start + n > m.len() {
        return false;
    }
    for i in 0..n {
        let src = (v as *const u8).offset((i as i64 * stride) as isize) as *const f64;
        m[start + i].t.value = std::mem::transmute::<[f64; 3], CVec3F64>(std::ptr::read_unaligned(src as *const [f64; 3])).into();
    }
    true
}
