/// Reads `xy` of elements `start..start + n` into slots `stride` bytes
/// apart; false when the range exceeds the collection.
#[no_mangle]
pub unsafe extern "C" fn scene_observations_get_xy_n(
    p: *const SceneHandle, start: u32, out: *mut f64, n: u32, stride: i64) -> bool {
    let m = &(*p).model.observations;
    let (start, n) = (start as usize, n as usize);
    if start + n > m.len() {
        return false;
    }
    for i in 0..n {
        let dst = (out as *mut u8).offset((i as i64 * stride) as isize) as *mut f64;
        let mv: CVec2F64 = m[start + i].xy.into();
        std::ptr::write_unaligned(dst as *mut [f64; 2], std::mem::transmute::<CVec2F64, [f64; 2]>(mv));
    }
    true
}
