/// Assigns a slot record's masked leaves onto a `Camera`: 1 mask
/// word(s), then 12 slot(s), one per leaf in field order.
#[allow(dead_code)]
unsafe fn assign_slots_camera(e: &mut Camera, s: *const u64) {
    if *s.add(0) & (1u64 << 0) != 0 {
        e.t.value = std::mem::transmute::<[f64; 3], CVec3F64>([f64::from_bits(*s.add(1)), f64::from_bits(*s.add(2)), f64::from_bits(*s.add(3))]).into();
    }
    if *s.add(0) & (1u64 << 1) != 0 {
        e.t.optimize = *s.add(4) != 0;
    }
    if *s.add(0) & (1u64 << 2) != 0 {
        e.ea.value = std::mem::transmute::<[f64; 3], CVec3F64>([f64::from_bits(*s.add(5)), f64::from_bits(*s.add(6)), f64::from_bits(*s.add(7))]).into();
    }
    if *s.add(0) & (1u64 << 3) != 0 {
        e.ea.optimize = *s.add(8) != 0;
    }
    if *s.add(0) & (1u64 << 4) != 0 {
        e.intr.value = std::mem::transmute::<[f64; 3], CVec3F64>([f64::from_bits(*s.add(9)), f64::from_bits(*s.add(10)), f64::from_bits(*s.add(11))]).into();
    }
    if *s.add(0) & (1u64 << 5) != 0 {
        e.intr.optimize = *s.add(12) != 0;
    }
}

/// Assigns a slot record's masked leaves onto a `Obs`: 1 mask
/// word(s), then 4 slot(s), one per leaf in field order.
#[allow(dead_code)]
unsafe fn assign_slots_obs(e: &mut Obs, s: *const u64) {
    if *s.add(0) & (1u64 << 0) != 0 {
        e.cam = arael::refs::Ref::from_raw(*s.add(1) as u32);
    }
    if *s.add(0) & (1u64 << 1) != 0 {
        e.pt = arael::refs::Ref::from_raw(*s.add(2) as u32);
    }
    if *s.add(0) & (1u64 << 2) != 0 {
        e.xy = std::mem::transmute::<[f64; 2], CVec2F64>([f64::from_bits(*s.add(3)), f64::from_bits(*s.add(4))]).into();
    }
}

/// Assigns a slot record's masked leaves onto a `Point`: 1 mask
/// word(s), then 4 slot(s), one per leaf in field order.
#[allow(dead_code)]
unsafe fn assign_slots_point(e: &mut Point, s: *const u64) {
    if *s.add(0) & (1u64 << 0) != 0 {
        e.pos.value = std::mem::transmute::<[f64; 3], CVec3F64>([f64::from_bits(*s.add(1)), f64::from_bits(*s.add(2)), f64::from_bits(*s.add(3))]).into();
    }
    if *s.add(0) & (1u64 << 1) != 0 {
        e.pos.optimize = *s.add(4) != 0;
    }
}
